import { useMemo, useState } from 'react';
import { JxButton, JxChip, JxBadge, JxEmptyState } from '@jinx-ui/react';

type ProjectStatus = 'active' | 'at-risk' | 'over-quota' | 'completed';

interface Project {
  id: string;
  name: string;
  status: ProjectStatus;
  quotaPercent: number;
}

interface StatusMeta {
  label: string;
  tone: 'success' | 'warning' | 'danger' | 'neutral';
  token: string;
}

const STATUS_META: Record<ProjectStatus, StatusMeta> = {
  active: { label: 'Активен', tone: 'success', token: 'var(--jx-color-success)' },
  'at-risk': { label: 'Под риском', tone: 'warning', token: 'var(--jx-color-warning)' },
  'over-quota': { label: 'Квота превышена', tone: 'danger', token: 'var(--jx-color-danger)' },
  completed: { label: 'Завершён', tone: 'neutral', token: 'var(--jx-color-neutral)' },
};

const ALL_STATUSES = Object.keys(STATUS_META) as ProjectStatus[];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Apollo', status: 'active', quotaPercent: 42 },
  { id: 'p2', name: 'Meridian', status: 'at-risk', quotaPercent: 87 },
  { id: 'p3', name: 'Zephyr', status: 'over-quota', quotaPercent: 118 },
  { id: 'p4', name: 'Nimbus', status: 'completed', quotaPercent: 100 },
  { id: 'p5', name: 'Solace', status: 'active', quotaPercent: 63 },
  { id: 'p6', name: 'Vertex', status: 'at-risk', quotaPercent: 91 },
  { id: 'p7', name: 'Halcyon', status: 'over-quota', quotaPercent: 132 },
  { id: 'p8', name: 'Ember', status: 'completed', quotaPercent: 100 },
  { id: 'p9', name: 'Quartz', status: 'active', quotaPercent: 25 },
  { id: 'p10', name: 'Orbit', status: 'at-risk', quotaPercent: 84 },
  { id: 'p11', name: 'Cascade', status: 'over-quota', quotaPercent: 145 },
  { id: 'p12', name: 'Lumen', status: 'completed', quotaPercent: 100 },
];

const PAGE_SIZE = 5;

function QuotaCircle({ percent, token }: { percent: number; token: string }) {
  const clamped = Math.min(100, Math.max(0, percent));
  const radius = 16;
  const circumference = 2 * Math.PI * radius;
  const offset = circumference - (clamped / 100) * circumference;

  return (
    <span style={{ display: 'inline-flex', width: 40, height: 40, flexShrink: 0 }}>
      <svg width={40} height={40} viewBox="0 0 40 40" role="img" aria-label={`Заполнено на ${clamped}%`}>
        <circle cx={20} cy={20} r={radius} fill="none" stroke="var(--jx-color-border)" strokeWidth={4} />
        <circle
          cx={20}
          cy={20}
          r={radius}
          fill="none"
          stroke={token}
          strokeWidth={4}
          strokeDasharray={circumference}
          strokeDashoffset={offset}
          strokeLinecap="round"
          transform="rotate(-90 20 20)"
        />
        <text x={20} y={23} textAnchor="middle" fontSize={10} fill="var(--jx-color-text)">
          {clamped}%
        </text>
      </svg>
    </span>
  );
}

export default function ProjectSpendPanel() {
  const [selectedStatuses, setSelectedStatuses] = useState<Set<ProjectStatus>>(new Set(ALL_STATUSES));
  const [page, setPage] = useState(1);

  const filtered = useMemo(
    () => PROJECTS.filter((project) => selectedStatuses.has(project.status)),
    [selectedStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const pageItems = filtered.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const removeStatus = (status: ProjectStatus) => {
    setSelectedStatuses((prev) => {
      const next = new Set(prev);
      next.delete(status);
      return next;
    });
    setPage(1);
  };

  const resetFilters = () => {
    setSelectedStatuses(new Set(ALL_STATUSES));
    setPage(1);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-md)' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-sm)' }}>
        {ALL_STATUSES.filter((status) => selectedStatuses.has(status)).map((status) => (
          <JxChip key={status} onRemove={() => removeStatus(status)}>
            {STATUS_META[status].label}
          </JxChip>
        ))}
      </div>

      {filtered.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          description="Снимите часть фильтров или сбросьте их, чтобы увидеть расходы по проектам."
        >
          <JxButton variant="primary" onClick={resetFilters}>
            Сбросить фильтры
          </JxButton>
        </JxEmptyState>
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-sm)' }}>
            {pageItems.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-md)',
                  padding: 'var(--jx-space-sm) var(--jx-space-md)',
                  border: '1px solid var(--jx-color-border)',
                  borderRadius: 'var(--jx-radius-md)',
                }}
              >
                <span style={{ flex: 1, fontWeight: 600, color: 'var(--jx-color-text)' }}>{project.name}</span>
                <QuotaCircle percent={project.quotaPercent} token={STATUS_META[project.status].token} />
                <JxBadge tone={STATUS_META[project.status].tone}>{STATUS_META[project.status].label}</JxBadge>
              </div>
            ))}
          </div>

          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 'var(--jx-space-sm)' }}>
            <JxButton
              variant="ghost"
              disabled={safePage === 1}
              onClick={() => setPage((current) => Math.max(1, current - 1))}
            >
              Назад
            </JxButton>
            <span style={{ color: 'var(--jx-color-text-secondary)' }}>
              Страница {safePage} из {pageCount}
            </span>
            <JxButton
              variant="ghost"
              disabled={safePage === pageCount}
              onClick={() => setPage((current) => Math.min(pageCount, current + 1))}
            >
              Далее
            </JxButton>
          </div>
        </>
      )}
    </div>
  );
}

